<?php
if(!defined('ABSPATH')){exit;}global $wpdb;
$products=SPF_Database::table('products');$lots=SPF_Database::table('lots');$sales=SPF_Database::table('sales');$items=SPF_Database::table('sale_items');$movements=SPF_Database::table('stock_movements');
$tz=wp_timezone();$today=new DateTimeImmutable('today',$tz);$tomorrow=$today->modify('+1 day');$month_start=$today->modify('first day of this month');$chart_start=$today->modify('-13 days');$top_start=$today->modify('-29 days');$expiry60=$today->modify('+60 days');$expiry90=$today->modify('+90 days');
$product_count=(int)$wpdb->get_var("SELECT COUNT(*) FROM $products WHERE status='active'");
$out_stock=(int)$wpdb->get_var("SELECT COUNT(*) FROM $products p WHERE p.status='active' AND COALESCE((SELECT SUM(l.quantity) FROM $lots l WHERE l.product_id=p.id),0)<=0");
$low_stock=(int)$wpdb->get_var("SELECT COUNT(*) FROM $products p WHERE p.status='active' AND p.stock_min>0 AND COALESCE((SELECT SUM(l.quantity) FROM $lots l WHERE l.product_id=p.id),0)<=p.stock_min");
$expiring=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $lots l INNER JOIN $products p ON p.id=l.product_id WHERE p.status='active' AND l.quantity>0 AND l.expiry_date IS NOT NULL AND l.expiry_date<>'0000-00-00' AND l.expiry_date>=%s AND l.expiry_date<=%s",$today->format('Y-m-d'),$expiry60->format('Y-m-d')));
$today_sales=(float)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(total),0) FROM $sales WHERE status='completed' AND created_at>=%s AND created_at<%s",$today->format('Y-m-d H:i:s'),$tomorrow->format('Y-m-d H:i:s')));
$month_sales=(float)$wpdb->get_var($wpdb->prepare("SELECT COALESCE(SUM(total),0) FROM $sales WHERE status='completed' AND created_at>=%s AND created_at<%s",$month_start->format('Y-m-d H:i:s'),$tomorrow->format('Y-m-d H:i:s')));
$today_count=(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM $sales WHERE status='completed' AND created_at>=%s AND created_at<%s",$today->format('Y-m-d H:i:s'),$tomorrow->format('Y-m-d H:i:s')));$avg_ticket=$today_count>0?$today_sales/$today_count:0;
$stock_value=(float)$wpdb->get_var("SELECT COALESCE(SUM(l.quantity*p.sale_price),0) FROM $lots l INNER JOIN $products p ON p.id=l.product_id WHERE p.status='active' AND l.quantity>0");$stock_units=(int)$wpdb->get_var("SELECT COALESCE(SUM(l.quantity),0) FROM $lots l INNER JOIN $products p ON p.id=l.product_id WHERE p.status='active'");
$daily_rows=$wpdb->get_results($wpdb->prepare("SELECT DATE(created_at) sale_date,COALESCE(SUM(total),0) total,COUNT(*) sales_count FROM $sales WHERE status='completed' AND created_at>=%s AND created_at<%s GROUP BY DATE(created_at) ORDER BY sale_date ASC",$chart_start->format('Y-m-d H:i:s'),$tomorrow->format('Y-m-d H:i:s')),ARRAY_A);$daily_map=[];$max_daily=0;foreach($daily_rows as $row){$daily_map[$row['sale_date']]=$row;$max_daily=max($max_daily,(float)$row['total']);}$daily_chart=[];for($i=13;$i>=0;$i--){$date=$today->modify('-'.$i.' days')->format('Y-m-d');$daily_chart[]=$daily_map[$date]??['sale_date'=>$date,'total'=>0,'sales_count'=>0];}
$top_products=$wpdb->get_results($wpdb->prepare("SELECT si.product_name,SUM(si.quantity) qty,SUM(si.total) total FROM $items si INNER JOIN $sales s ON s.id=si.sale_id WHERE s.status='completed' AND s.created_at>=%s AND s.created_at<%s GROUP BY si.product_id,si.product_name ORDER BY qty DESC,total DESC LIMIT 8",$top_start->format('Y-m-d H:i:s'),$tomorrow->format('Y-m-d H:i:s')),ARRAY_A);
$low_rows=$wpdb->get_results("SELECT p.id,p.name,p.barcode,p.stock_min,COALESCE(SUM(l.quantity),0) stock FROM $products p LEFT JOIN $lots l ON l.product_id=p.id WHERE p.status='active' GROUP BY p.id HAVING (p.stock_min>0 AND stock<=p.stock_min) OR stock<=0 ORDER BY stock ASC,p.name ASC LIMIT 10",ARRAY_A);
$expiring_rows=$wpdb->get_results($wpdb->prepare("SELECT l.*,p.name product_name,p.barcode FROM $lots l INNER JOIN $products p ON p.id=l.product_id WHERE p.status='active' AND l.quantity>0 AND l.expiry_date IS NOT NULL AND l.expiry_date<>'0000-00-00' AND l.expiry_date>=%s AND l.expiry_date<=%s ORDER BY l.expiry_date ASC LIMIT 10",$today->format('Y-m-d'),$expiry90->format('Y-m-d')),ARRAY_A);
$kardex_rows=$wpdb->get_results("SELECT m.*,p.name product_name,p.barcode,l.lot_number FROM $movements m LEFT JOIN $products p ON p.id=m.product_id LEFT JOIN $lots l ON l.id=m.lot_id ORDER BY m.id DESC LIMIT 20",ARRAY_A);
$recent_sales=$wpdb->get_results("SELECT s.*,GROUP_CONCAT(CONCAT(si.product_name,' x',si.quantity) ORDER BY si.id SEPARATOR ', ') items FROM $sales s LEFT JOIN $items si ON si.sale_id=s.id GROUP BY s.id ORDER BY s.id DESC LIMIT 8",ARRAY_A);
$documents=SPF_Config::sales_documents();$payments=SPF_Config::payment_methods();$doc_label=function($code)use($documents){$meta=$documents[$code]??$code;return is_array($meta)?($meta['label']??$code):$meta;};$movement_labels=['purchase'=>__('Entrada','sistema-para-farmacias'),'sale'=>__('Venta','sistema-para-farmacias'),'adjustment'=>__('Ajuste','sistema-para-farmacias'),'return'=>__('Devolución','sistema-para-farmacias'),'expired'=>__('Vencido','sistema-para-farmacias'),'loss'=>__('Merma','sistema-para-farmacias')];$home_id=absint(get_option('spf_home_page_id',0));$home_url=$home_id&&get_post_status($home_id)?get_permalink($home_id):'';
?>
<div class="wrap spf-wrap spf-dashboard"><div class="spf-dashboard-head"><div><h1><?php esc_html_e('Dashboard','sistema-para-farmacias'); ?></h1><p><?php esc_html_e('Resumen operativo de ventas, inventario, vencimientos y kardex.','sistema-para-farmacias'); ?></p></div><div class="spf-dashboard-actions"><?php if(current_user_can(SPF_Roles::SELL)||current_user_can('manage_options')): ?><a class="button button-primary" href="<?php echo esc_url(admin_url('admin.php?page=spf-pos')); ?>"><?php esc_html_e('Abrir POS','sistema-para-farmacias'); ?></a><?php endif; ?><?php if($home_url): ?><a class="button" href="<?php echo esc_url($home_url); ?>"><?php esc_html_e('Abrir inicio del sistema','sistema-para-farmacias'); ?></a><?php endif; ?></div></div>
<div class="spf-cards spf-kpi-grid"><div class="spf-card"><strong><?php echo esc_html(SPF_Config::money($today_sales)); ?></strong><span><?php esc_html_e('Ventas hoy','sistema-para-farmacias'); ?></span></div><div class="spf-card"><strong><?php echo esc_html(SPF_Config::money($month_sales)); ?></strong><span><?php esc_html_e('Ventas del mes','sistema-para-farmacias'); ?></span></div><div class="spf-card"><strong><?php echo esc_html(SPF_Config::money($avg_ticket)); ?></strong><span><?php esc_html_e('Ticket promedio hoy','sistema-para-farmacias'); ?></span></div><div class="spf-card"><strong><?php echo esc_html($today_count); ?></strong><span><?php esc_html_e('Ventas realizadas hoy','sistema-para-farmacias'); ?></span></div><div class="spf-card"><strong><?php echo esc_html($product_count); ?></strong><span><?php esc_html_e('Productos activos','sistema-para-farmacias'); ?></span></div><div class="spf-card"><strong><?php echo esc_html($stock_units); ?></strong><span><?php esc_html_e('Unidades en stock','sistema-para-farmacias'); ?></span></div><div class="spf-card"><strong><?php echo esc_html(SPF_Config::money($stock_value)); ?></strong><span><?php esc_html_e('Valor del stock a precio de venta','sistema-para-farmacias'); ?></span></div><div class="spf-card"><strong><?php echo esc_html($low_stock); ?></strong><span><?php esc_html_e('Stock bajo','sistema-para-farmacias'); ?></span></div><div class="spf-card danger"><strong><?php echo esc_html($out_stock); ?></strong><span><?php esc_html_e('Sin stock','sistema-para-farmacias'); ?></span></div><div class="spf-card warning"><strong><?php echo esc_html($expiring); ?></strong><span><?php esc_html_e('Lotes que vencen en 60 días','sistema-para-farmacias'); ?></span></div></div>
<div class="spf-dashboard-grid"><section class="spf-panel"><h2><?php esc_html_e('Ventas por día · últimos 14 días','sistema-para-farmacias'); ?></h2><div class="spf-chart-scroll"><div class="spf-chart-bars"><?php foreach($daily_chart as $row): $total=(float)$row['total'];$height=$max_daily>0?max(8,round(($total/$max_daily)*160)):8;$label=wp_date('d/m',strtotime($row['sale_date'])); ?><div class="spf-bar-item" title="<?php echo esc_attr($label.' · '.SPF_Config::money($total)); ?>"><div class="spf-bar-value"><?php echo esc_html(number_format_i18n($total,0)); ?></div><div class="spf-bar" style="height:<?php echo esc_attr($height); ?>px"></div><span><?php echo esc_html($label); ?></span></div><?php endforeach; ?></div></div></section><section class="spf-panel"><h2><?php esc_html_e('Productos más vendidos · últimos 30 días','sistema-para-farmacias'); ?></h2><div class="spf-ranking"><?php if($top_products): foreach($top_products as $index=>$row): ?><div class="spf-ranking-row"><span class="spf-ranking-position"><?php echo esc_html($index+1); ?></span><span class="spf-ranking-name"><strong><?php echo esc_html($row['product_name']); ?></strong><small><?php echo esc_html(sprintf(__('%d unidades','sistema-para-farmacias'),(int)$row['qty'])); ?></small></span><strong class="spf-ranking-total"><?php echo esc_html(SPF_Config::money($row['total'])); ?></strong></div><?php endforeach; else: ?><p><?php esc_html_e('Todavía no hay ventas suficientes.','sistema-para-farmacias'); ?></p><?php endif; ?></div></section></div>
<div class="spf-dashboard-grid"><section class="spf-panel"><h2><?php esc_html_e('Alertas de stock','sistema-para-farmacias'); ?></h2><div class="spf-table-scroll spf-table-compact"><table class="widefat striped"><thead><tr><th><?php esc_html_e('Producto','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Código','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Stock','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Mínimo','sistema-para-farmacias'); ?></th></tr></thead><tbody><?php if($low_rows):foreach($low_rows as $row): ?><tr><td><strong><?php echo esc_html($row['name']); ?></strong></td><td><?php echo esc_html($row['barcode']); ?></td><td><span class="spf-badge danger"><?php echo esc_html((int)$row['stock']); ?></span></td><td><?php echo esc_html((int)$row['stock_min']); ?></td></tr><?php endforeach;else: ?><tr><td colspan="4"><?php esc_html_e('No hay productos con stock bajo.','sistema-para-farmacias'); ?></td></tr><?php endif; ?></tbody></table></div></section><section class="spf-panel"><h2><?php esc_html_e('Próximos vencimientos','sistema-para-farmacias'); ?></h2><div class="spf-table-scroll spf-table-compact"><table class="widefat striped"><thead><tr><th><?php esc_html_e('Producto','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Lote','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Vence','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Cant.','sistema-para-farmacias'); ?></th></tr></thead><tbody><?php if($expiring_rows):foreach($expiring_rows as $row): ?><tr><td><strong><?php echo esc_html($row['product_name']); ?></strong></td><td><?php echo esc_html($row['lot_number']); ?></td><td><?php echo esc_html(wp_date(get_option('date_format'),strtotime($row['expiry_date']))); ?></td><td><?php echo esc_html((int)$row['quantity']); ?></td></tr><?php endforeach;else: ?><tr><td colspan="4"><?php esc_html_e('No hay lotes próximos a vencer.','sistema-para-farmacias'); ?></td></tr><?php endif; ?></tbody></table></div></section></div>
<section class="spf-panel"><h2><?php esc_html_e('Kardex / últimos movimientos de inventario','sistema-para-farmacias'); ?></h2><div class="spf-table-scroll spf-table-wide"><table class="widefat striped"><thead><tr><th><?php esc_html_e('Fecha','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Producto','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Código','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Lote','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Movimiento','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Cant.','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Antes','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Después','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Motivo','sistema-para-farmacias'); ?></th></tr></thead><tbody><?php if($kardex_rows):foreach($kardex_rows as $row):$qty=(int)$row['quantity']; ?><tr><td><?php echo esc_html(wp_date(get_option('date_format').' '.get_option('time_format'),strtotime($row['created_at']))); ?></td><td><strong><?php echo esc_html($row['product_name']?:__('Producto eliminado','sistema-para-farmacias')); ?></strong></td><td><?php echo esc_html($row['barcode']); ?></td><td><?php echo esc_html($row['lot_number']?:'—'); ?></td><td><span class="spf-badge <?php echo esc_attr($row['movement_type']==='sale'?'neutral':'ok'); ?>"><?php echo esc_html($movement_labels[$row['movement_type']]??$row['movement_type']); ?></span></td><td class="<?php echo $qty<0?'spf-negative':'spf-positive'; ?>"><?php echo esc_html(($qty>0?'+':'').$qty); ?></td><td><?php echo esc_html((int)$row['previous_stock']); ?></td><td><?php echo esc_html((int)$row['new_stock']); ?></td><td><?php echo esc_html(wp_trim_words($row['reason'],8)); ?></td></tr><?php endforeach;else: ?><tr><td colspan="9"><?php esc_html_e('Todavía no hay movimientos de inventario.','sistema-para-farmacias'); ?></td></tr><?php endif; ?></tbody></table></div></section>
<section class="spf-panel"><h2><?php esc_html_e('Últimas ventas','sistema-para-farmacias'); ?></h2><div class="spf-table-scroll spf-table-wide"><table class="widefat striped"><thead><tr><th><?php esc_html_e('Número','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Productos','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Documento','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Pago','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Total','sistema-para-farmacias'); ?></th><th><?php esc_html_e('Fecha','sistema-para-farmacias'); ?></th></tr></thead><tbody><?php if($recent_sales):foreach($recent_sales as $row): ?><tr><td><strong><?php echo esc_html($row['sale_number']); ?></strong></td><td><?php echo esc_html($row['items']?:'—'); ?></td><td><?php echo esc_html($doc_label($row['document_type'])); ?></td><td><?php echo esc_html($payments[$row['payment_method']]??$row['payment_method']); ?></td><td><strong><?php echo esc_html(SPF_Config::money($row['total'])); ?></strong></td><td><?php echo esc_html(wp_date(get_option('date_format').' '.get_option('time_format'),strtotime($row['created_at']))); ?></td></tr><?php endforeach;else: ?><tr><td colspan="6"><?php esc_html_e('Todavía no hay ventas registradas.','sistema-para-farmacias'); ?></td></tr><?php endif; ?></tbody></table></div></section></div>
